html = java.ajax(url);
a = org.jsoup.Jsoup.parse(html)
.select("nav.nav li:gt(0):lt(12) a");
var arr = [], sort = [];
if (html && a) {
  arr = Array.from(a, x => ([
    x.text(), String(x.attr("href"))
    .replace(/1.?$/, "{{page}}/")
    .replace(/class.*(?!1).?$/,
      "$&<,{{page}}/>")
    .replace(/quanben.+(?!1).?$/,
      "$&<,{{page}}/>")]) );
  sort = arr.map(([title, link])=>({
    "title": title,
    "url": link,
    "style": {
      "layout_flexGrow": 1,
      "layout_flexBasisPercent": 0.2
    }
  }));

  JSON.stringify(sort);

} else java.toast("发现列表获取失败！");

ruleToc.chapterList:
+@js:
var reg=new RegExp(/<dd(.).+?"(\d+\.html)">(.*?)<\/a>/g);
var list1=[];
var list2=[];
var tmp,url,name;
var i=-1;
while((tmp=reg.exec(result))){
url=tmp[2];
name=tmp[3];
if(tmp[1].match(/>/)){
i=i+1;
list1.push({name:name,url:url});
}
else
list2.push({name:name,url:url});

if(i==1){
i=-1;
list1=list1.concat(list2.reverse());
list2=[];
}
}
list1;

